import {ALL_CHARACTERS,CHARACTER_INDEX,ALL_PARTS,CREATIONS,CREATION_INDEX,LAYOUTS,matchCreation,CATEGORIES,DISCOVERIES} from './creation-data.mjs';
import {CreationWorld,CREATION_SAVE_KEY,MAX_OBJECTS} from './creation-engine.mjs';
import {renderPainting,escapeXML as esc} from './creation-art.mjs';
const $=s=>document.querySelector(s),dialog=$('#creation-dialog');
let world=new CreationWorld(),saveWorks=true,recovered=false,mode='char',layout='single',slots=[null],words=[],pending=null,selected=null,tool='hand',labels=false,focusSlot=null,drag=null;
try{const raw=localStorage.getItem(CREATION_SAVE_KEY);if(raw&&raw.length<1500000){try{world=CreationWorld.restore(JSON.parse(raw));}catch{recovered=true;}}else if(!raw){const old=localStorage.getItem('wordward-glyph-save-v1');if(old&&old.length<100000)try{world.migrateLessons(JSON.parse(old));}catch{}}}catch{saveWorks=false;}
function syncViewport(){const installed=navigator.standalone===true||matchMedia('(display-mode: standalone)').matches;document.documentElement.dataset.creationStandalone=String(installed);if(installed)document.documentElement.style.removeProperty('--c-height');else document.documentElement.style.setProperty('--c-height',innerHeight+'px');}
syncViewport();for(const event of ['resize','orientationchange','pageshow'])window.addEventListener(event,syncViewport);visualViewport?.addEventListener('resize',syncViewport);matchMedia('(display-mode: standalone)').addEventListener('change',syncViewport);
for(const event of ['selectstart','contextmenu','dblclick'])document.addEventListener(event,e=>e.preventDefault());for(const event of ['gesturestart','gesturechange'])document.addEventListener(event,e=>e.preventDefault(),{passive:false});document.addEventListener('touchmove',e=>{if(e.touches.length>1)e.preventDefault();},{passive:false});document.addEventListener('wheel',e=>{if(e.ctrlKey)e.preventDefault();},{passive:false});
function feedback(message,success=false){$('#creation-feedback').textContent=message;$('#creation-feedback').classList.toggle('success',success);$('#creation-live').textContent=message;}
function save(){try{localStorage.setItem(CREATION_SAVE_KEY,JSON.stringify(world.export()));saveWorks=true;}catch{saveWorks=false;}$('#creation-save-status').textContent=saveWorks?'✓ 画卷自动保存 · 当前浏览器':'暂时无法保存，仍可继续造物';}
function renderWorld(){
 $('#creation-world').innerHTML=renderPainting(world.scene,{selected,labels});$('#creation-world').classList.toggle('is-placing',!!pending);$('#creation-world').classList.toggle('is-erasing',tool==='erase'&&!pending);
 $('#creation-title').innerHTML=esc(world.scene.title)+' <small>✎</small>';$('#creation-count').textContent=world.scene.objects.length?`${world.scene.objects.length} / ${MAX_OBJECTS} 处造物`:'空白画卷';
 $('#creation-placement').textContent=pending?`待落笔：${pending} · 点画卷，可以反复放置`:tool==='erase'?'点一个造物，把它从画卷里移开':world.scene.objects.length?'拖动造物安排位置 · 点选可看字义':'造一个「人」、一汪「水」，或者让「雨」落下来';$('#creation-world-tip').classList.toggle('ready',!!pending);$('#creation-cancel').hidden=!pending;
 $('#creation-undo').disabled=!world.undoStack.length;$('#creation-hand').classList.toggle('active',tool==='hand');$('#creation-eraser').classList.toggle('active',tool==='erase');$('#creation-labels').classList.toggle('active',labels);
 $('#creation-discoveries').textContent=world.discoveries.length?`✧ ${world.discoveries.length} 次奇妙相遇 · ${world.knownChars.length} 个字`:`${world.knownChars.length} 个字可用 · 试试让它们相遇`;
 const object=world.scene.objects.find(e=>e.id===selected);$('#creation-selection').hidden=!object;if(object)$('#creation-selection').innerHTML=`<b>${esc(object.text)}</b><span>可拖动</span><button data-selected-detail="${object.text}">字义</button><button data-restyle="${object.id}">换样</button><button data-resize="${object.id}">大小</button><button class="remove" data-remove="${object.id}">移开</button>`;
}
function currentResult(){return mode==='char'?slots.every(Boolean)?matchCreation(layout,slots):null:words.length>=2?CREATION_INDEX.get(words.join('')):null;}
function renderWorkshop(){
 for(const b of document.querySelectorAll('[data-creation-mode]'))b.setAttribute('aria-pressed',String(b.dataset.creationMode===mode));
 $('#creation-layouts').classList.toggle('word-mode',mode==='word');$('#creation-layouts').innerHTML=mode==='char'?Object.entries(LAYOUTS).map(([id,s])=>`<button data-layout="${id}" aria-pressed="${layout===id}">${s.name}</button>`).join(''):'按词序选 2—4 个字 · 字可重复使用';
 const list=mode==='char'?slots:Array.from({length:4},(_,i)=>words[i]||null),grid=$('#creation-slots');grid.dataset.layout=mode==='word'?'word':layout;grid.dataset.outer=slots[0]||'';grid.innerHTML=list.map((p,i)=>`<button class="c-slot ${p?'':'empty'}" data-slot="${i}" aria-label="${mode==='char'?LAYOUTS[layout].positions[i]:`第 ${i+1} 字`}，${p?esc(p)+'，点击移走':'待放入'}">${p?esc(p):mode==='char'?LAYOUTS[layout].positions[i]:['一','二','三','四'][i]}</button>`).join('');
 const result=currentResult(),text=mode==='char'?result?.char:result?.text,creation=CREATION_INDEX.get(text);
 $('#creation-preview').innerHTML=result?`<b class="${mode==='word'?'c-word-preview':''}">${esc(text)}</b><small>${mode==='char'?esc(result.pinyin):[...text].map(c=>esc(CHARACTER_INDEX.get(c)?.pinyin||'')).join(' ')}</small><p>${esc(creation?.meaning||result.meaning)}</p><span class="c-tag">${creation?creation.category==='变化'?'改变画卷':creation.category+' · 可落笔':CREATIONS.some(c=>c.isWord&&c.text.includes(text))?'收入字册 · 可继续组词':'收入字册 · 学习字形字义'}</span>`:`<b class="c-empty-preview">${mode==='char'?'让想象<br>长出来':'字与字<br>再相遇'}</b><small>${mode==='char'?'选择摆法，再放进部件':'先造字，再按词序组合'}</small>`;
 const ready=mode==='char'?!!result:!!result?.isWord;$('#creation-forge').disabled=!ready;$('#creation-forge').textContent=ready?creation?`造出「${text}」，去落笔 →`:`认识「${text}」，收进字袋 →`:mode==='char'?'选部件，造一个字 →':'选汉字，组一个词 →';
 $('#creation-parts-title').textContent=mode==='char'?'灵感部件':'常用字牌';$('#creation-parts-more').textContent=mode==='char'?`全部 ${Object.keys(ALL_PARTS).length} 部件 ↗`:'全部汉字 ↗';
 const candidates=mode==='char'?world.recommendations:wordCandidates();$('#creation-parts').innerHTML=candidates.map(p=>partButton(p,mode==='word')).join('');
}
function wordCandidates(){const missing=world.availableWords.filter(c=>!world.knownWords.includes(c.text)),suggestions=world.shuffle(missing).slice(0,3).flatMap(c=>[...c.text]);const preferred=[...new Set([...suggestions,...world.knownChars.slice(-10),...world.knownChars])];return preferred.slice(0,12);}
function partButton(part,isChar=false){const name=isChar?CHARACTER_INDEX.get(part)?.pinyin:ALL_PARTS[part]?.name;return`<button class="c-part ${[...part].length>1?'long':''}" ${isChar?'data-char':'data-part'}="${esc(part)}" aria-label="${esc(part)}，${esc(name||part)}"><b>${esc(part)}</b><small>${esc(name||'部件')}</small></button>`;}
function setMode(next){mode=next;focusSlot=null;renderWorkshop();}
function fillCharacter(char){const glyph=CHARACTER_INDEX.get(char);if(!glyph)return;mode='char';layout=glyph.layout;slots=[...glyph.parts];focusSlot=null;closeDialog();renderWorkshop();feedback(`试着把「${char}」造出来：${glyph.parts.join(' ＋ ')}。部件可以换，摆法也可以换。`);}
function selectPart(part){if(mode==='word'){if(words.length===4)return feedback('最多四个字。点一下格子里的字可以移走。');words.push(part);}else{const index=focusSlot??slots.indexOf(null);if(index<0)return feedback('格子已放满。点一下格子移走部件，或换一种摆法。');slots[index]=part;focusSlot=null;}renderWorkshop();const result=currentResult();if(!result&&(mode==='char'?slots.every(Boolean):words.length>=2))feedback(mode==='char'?'这组部件暂未收录。换个摆法，或去造物册找找配方。':'这个组合暂未收进造物册，不代表它不是词语。可以继续加字或调整词序。');}
$('#creation-layouts').onclick=e=>{const b=e.target.closest('[data-layout]');if(!b)return;const filled=slots.filter(Boolean);layout=b.dataset.layout;slots=LAYOUTS[layout].positions.map((_,i)=>filled[i]||null);focusSlot=null;renderWorkshop();};
for(const b of document.querySelectorAll('[data-creation-mode]'))b.onclick=()=>setMode(b.dataset.creationMode);
$('#creation-slots').onclick=e=>{const b=e.target.closest('[data-slot]');if(!b)return;const i=Number(b.dataset.slot);if(mode==='word'){words.splice(i,1);}else if(slots[i]){slots[i]=null;focusSlot=null;}else focusSlot=i;renderWorkshop();};
$('#creation-parts').onclick=e=>{const b=e.target.closest('[data-part],[data-char]');if(b)selectPart(b.dataset.part||b.dataset.char);};
$('#creation-clear').onclick=()=>{slots=slots.map(()=>null);words=[];focusSlot=null;renderWorkshop();};
$('#creation-refresh').onclick=()=>{world.refresh();renderWorkshop();save();feedback('换一把灵感，部件都能重复用。全部部件随时可以自由选。');};
$('#creation-forge').onclick=()=>{
 const result=mode==='char'?world.learn(layout,slots):world.word(words);if(!result.ok)return feedback(result.message);
 const text=mode==='char'?result.glyph.char:result.creation.text;pending=CREATION_INDEX.has(text)?text:null;selected=null;save();renderWorld();feedback(pending?`「${text}」备好啦！点画卷放下它，同一个字词可以反复落笔。`:`认识「${text}」啦！已收进字袋，${CREATIONS.some(c=>c.isWord&&c.text.includes(text))?'可以继续组词。':'可以随时查看拼音和字义。'}`,true);
};
function prepare(text){if(!world.canUse(text))return;pending=text;selected=null;tool='hand';closeDialog();renderWorld();feedback(`准备好了「${text}」，点画卷落笔吧。`,true);}
$('#creation-cancel').onclick=()=>{pending=null;renderWorld();};
$('#creation-hand').onclick=()=>{pending=null;tool='hand';renderWorld();};$('#creation-eraser').onclick=()=>{pending=null;tool=tool==='erase'?'hand':'erase';renderWorld();};$('#creation-labels').onclick=()=>{labels=!labels;renderWorld();};
$('#creation-undo').onclick=()=>{if(world.undo()){selected=null;renderWorld();save();feedback('撤回了上一次画卷变化。认识过的字和发现仍留在字册里。');}};
function drop(x,y){const result=world.place(pending,x,y);if(!result.ok)return feedback(result.message);selected=null;renderWorld();save();feedback(result.message,true);$('#creation-world').classList.remove('just-placed');requestAnimationFrame(()=>$('#creation-world').classList.add('just-placed'));}
function point(event){const svg=$('#creation-svg'),p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const matrix=svg.getScreenCTM();return matrix?p.matrixTransform(matrix.inverse()):{x:500,y:400};}
const worldElement=$('#creation-world');
worldElement.onpointerdown=e=>{if(drag||e.button!==0)return;const target=e.target.closest('[data-object]');const p=point(e);drag={pointer:e.pointerId,id:target?Number(target.dataset.object):null,start:p,x:e.clientX,y:e.clientY,moved:false};worldElement.setPointerCapture(e.pointerId);};
worldElement.onpointermove=e=>{if(!drag||drag.pointer!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moved=true;if(drag.moved&&drag.id&&!pending&&tool==='hand'){const object=world.scene.objects.find(o=>o.id===drag.id);if(!object)return;const p=point(e),group=$(`[data-object="${drag.id}"]`),scale=object.size*(1+object.growth*.1);const x=Math.max(45,Math.min(955,object.x+p.x-drag.start.x)),y=Math.max(100,Math.min(590,object.y+p.y-drag.start.y));group?.setAttribute('transform',`translate(${x} ${y}) scale(${scale})`);worldElement.classList.add('dragging');}};
worldElement.onpointerup=e=>{if(!drag||drag.pointer!==e.pointerId)return;const end=point(e),last=drag;drag=null;worldElement.classList.remove('dragging');if(worldElement.hasPointerCapture(e.pointerId))worldElement.releasePointerCapture(e.pointerId);if(last.moved){if(last.id&&!pending&&tool==='hand'){const object=world.scene.objects.find(o=>o.id===last.id);if(object){world.move(last.id,object.x+end.x-last.start.x,object.y+end.y-last.start.y);selected=last.id;save();renderWorld();}}return;}if(pending)return drop(end.x,end.y);if(last.id&&tool==='erase'){if(!world.remove(last.id))return feedback('这里还有鱼、船或荷花。先移开水中的造物，再移走最后一汪水。');selected=null;save();renderWorld();return;}selected=last.id;renderWorld();};
worldElement.onpointercancel=e=>{if(drag?.pointer!==e.pointerId)return;drag=null;worldElement.classList.remove('dragging');renderWorld();};
worldElement.onkeydown=e=>{const b=e.target.closest('[data-object]');if(!b)return;const id=Number(b.dataset.object);if(['Enter',' '].includes(e.key)){e.preventDefault();selected=id;renderWorld();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();world.remove(id);selected=null;save();renderWorld();}};
$('#creation-selection').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.restyle||b.dataset.resize){world.restyle(Number(b.dataset.restyle||b.dataset.resize),{variant:!!b.dataset.restyle,resize:!!b.dataset.resize});save();renderWorld();}else if(b.dataset.remove){if(!world.remove(Number(b.dataset.remove)))return feedback('先移开鱼、船或荷花，再移走最后一汪水。');selected=null;save();renderWorld();}else if(b.dataset.selectedDetail)openDetail(b.dataset.selectedDetail);};
function openDialog(html){$('#creation-dialog-content').innerHTML=html;$('#creation-dialog-content').onclick=null;if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();}
$('#creation-dialog-close').onclick=closeDialog;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function openParts(bag=false){
 const inWords=bag||mode==='word';openDialog(`<h2>${bag?'我的字袋':inWords?'选一个汉字':'挑选部件'}</h2><p class="c-subtitle">${inWords?'认识过的字可重复使用。点字查看，或者直接放入画卷。':`${Object.keys(ALL_PARTS).length} 种部件全部开放，不限使用次数。`}</p><input id="creation-part-search" class="c-search" type="search" inputmode="text" autocomplete="off" placeholder="${inWords?'搜汉字、拼音或字义':'搜部件、名称或想造的字'}" aria-label="搜索部件或汉字"><div class="c-filter" id="creation-part-filter">${(inWords?['全部汉字','可落笔','可组词']:['全部部件','常见偏旁','整字可用']).map((t,i)=>`<button data-part-filter="${i}" class="${i===0?'active':''}">${t}</button>`).join('')}</div><div class="c-drawer-grid" id="creation-part-grid"></div><p id="creation-part-progress" class="c-subtitle">${bag?'点一个字，看看能造什么。':'点选部件，放满组字格后会回到造物台。'}</p>`);
 let filter=0;const render=()=>{const search=$('#creation-part-search').value.trim().toLowerCase();const rows=inWords?world.knownChars.filter(c=>{const g=CHARACTER_INDEX.get(c);return(!filter||filter===1&&CREATION_INDEX.has(c)||filter===2&&CREATIONS.some(entry=>entry.isWord&&entry.text.includes(c)))&&(!search||[c,g.pinyin,g.meaning].some(t=>t.toLowerCase().includes(search)));}):Object.keys(ALL_PARTS).filter(p=>{const part=ALL_PARTS[p];return(!filter||filter===1&&part.radical||filter===2&&CHARACTER_INDEX.get(p)?.layout==='single')&&(!search||p.includes(search)||part.name.includes(search)||ALL_CHARACTERS.some(g=>g.char===search&&g.parts.includes(p)));});$('#creation-part-grid').innerHTML=rows.map(p=>partButton(p,inWords)).join('')||'<p>这次没有找到，换个字试试。</p>';};
 render();$('#creation-part-search').oninput=render;$('#creation-part-filter').onclick=e=>{const b=e.target.closest('[data-part-filter]');if(!b)return;filter=Number(b.dataset.partFilter);for(const x of $('#creation-part-filter').children)x.classList.toggle('active',x===b);render();};$('#creation-part-grid').onclick=e=>{const b=e.target.closest('[data-part],[data-char]');if(!b)return;const part=b.dataset.part||b.dataset.char;if(bag){if(CREATION_INDEX.has(part))return prepare(part);if(!CREATIONS.some(entry=>entry.isWord&&entry.text.includes(part)))return openDetail(part);closeDialog();setMode('word');selectPart(part);}else{selectPart(part);if(mode==='char'?slots.every(Boolean):!!currentResult()?.isWord)closeDialog();else $('#creation-part-progress').textContent=`已选：${(mode==='char'?slots.filter(Boolean):words).join('、')}。继续挑一个吧。`;}};
}
$('#creation-parts-more').onclick=()=>openParts();$('#creation-bag').onclick=()=>openParts(true);
function openBook(initial='objects'){
 openDialog(`<h2>造物册</h2><p class="c-subtitle">${ALL_CHARACTERS.length} 个字 · ${CREATIONS.filter(c=>c.isWord).length} 个造物词 · 全部配方开放，随时自由探索</p><div class="c-filter" id="creation-book-tabs"><button data-book-tab="objects" class="${initial==='objects'?'active':''}">造物与变化</button><button data-book-tab="characters" class="${initial==='characters'?'active':''}">汉字配方</button><button data-book-tab="discoveries" class="${initial==='discoveries'?'active':''}">奇妙相遇 ${world.discoveries.length}</button></div><input id="creation-book-search" class="c-search" type="search" autocomplete="off" placeholder="搜花、雨、山，或想造的字词" aria-label="搜索造物与汉字"><div class="c-filter" id="creation-book-category"></div><div class="c-book-grid" id="creation-book-grid"></div>`);
 let tab=initial,category='全部';const render=()=>{const q=$('#creation-book-search').value.trim();$('#creation-book-category').innerHTML=tab==='objects'?CATEGORIES.map(t=>`<button data-category="${t}" class="${t===category?'active':''}">${t}</button>`).join(''):'';
 const grid=$('#creation-book-grid');grid.className=tab==='discoveries'?'c-discovery-list':'c-book-grid';if(tab==='discoveries'){grid.innerHTML=world.discoveries.length?world.discoveries.map(id=>`<div><b>✧ ${DISCOVERIES[id].title}</b><p>${DISCOVERIES[id].meaning}</p></div>`).join(''):'<p>把不同造物放在一起，看看它们会有什么反应。不用照着任务做，发现会慢慢记在这里。</p>';return;}
 if(tab==='characters')grid.innerHTML=ALL_CHARACTERS.filter(g=>!q||[g.char,g.meaning,g.pinyin,...g.parts].some(t=>t.includes(q))).map(g=>`<button class="c-book-card" data-recipe="${g.char}"><b>${g.char} <small>${g.pinyin}</small></b><span class="c-formula">${g.parts.join(' ＋ ')}</span><small>${g.meaning}</small><span class="c-status">${LAYOUTS[g.layout].name} · ${world.knownChars.includes(g.char)?'已认识':'试着造出这个字'} ↗</span></button>`).join('');
 else grid.innerHTML=CREATIONS.filter(c=>(category==='全部'||category===c.category)&&(!q||c.text.includes(q)||c.meaning.includes(q))).map(c=>`<button class="c-book-card" data-creation-detail="${c.text}"><b>${c.text}</b><small>${c.meaning}</small><span class="c-status">${c.category} · ${world.canUse(c.text)?'已经备好，可以落笔':c.isWord?'先造字，再组词':'查看组字配方'} ↗</span></button>`).join('');};
 render();$('#creation-book-search').oninput=render;$('#creation-book-tabs').onclick=e=>{const b=e.target.closest('[data-book-tab]');if(!b)return;tab=b.dataset.bookTab;for(const x of $('#creation-book-tabs').children)x.classList.toggle('active',x===b);render();};$('#creation-book-category').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;render();}};$('#creation-book-grid').onclick=e=>{const b=e.target.closest('[data-recipe],[data-creation-detail]');if(b?.dataset.recipe)fillCharacter(b.dataset.recipe);else if(b)openDetail(b.dataset.creationDetail);};
}
$('#creation-book').onclick=()=>openBook();
function openDetail(text){const c=CREATION_INDEX.get(text),g=CHARACTER_INDEX.get(text);if(!c&&!g)return;const missing=c?.isWord?[...new Set([...text].filter(ch=>!world.knownChars.includes(ch)))]:[];
 openDialog(`<h2>${esc(text)}</h2><div class="c-detail-char">${esc(text)}</div>${g?`<small>${g.pinyin} · ${LAYOUTS[g.layout].name}</small><div class="c-detail-formula">${g.parts.join(' ＋ ')} → ${g.char}</div>`:''}<p>${esc(c?.meaning||g.meaning)}</p>${missing.length?`<div class="c-note">先造出这些字：${missing.join('、')}。每个字都能在配方里找到。</div>`:''}<div class="c-dialog-actions">${world.canUse(text)?'<button id="creation-detail-place" class="c-primary">备好，放入画卷 →</button>':g?`<button data-fill-char="${g.char}" class="c-primary">试着造出「${g.char}」 →</button>`:missing.length?missing.map(ch=>`<button data-fill-char="${ch}" class="c-secondary">先造「${ch}」</button>`).join(''):'<button id="creation-detail-word" class="c-primary">去组出这个词 →</button>'}<button id="creation-detail-book" class="c-secondary">回到造物册</button></div>`);
 $('#creation-dialog-content').onclick=e=>{const b=e.target.closest('[data-fill-char]');if(b)fillCharacter(b.dataset.fillChar);};$('#creation-detail-book').onclick=()=>openBook();if($('#creation-detail-place'))$('#creation-detail-place').onclick=()=>prepare(text);if($('#creation-detail-word'))$('#creation-detail-word').onclick=()=>{mode='word';words=[...text];closeDialog();renderWorkshop();feedback(`按顺序组出「${text}」，然后放进画卷。`);};
}
$('#creation-inspire').onclick=()=>{const candidates=CREATIONS.filter(c=>c.isWord&&c.text.length>=3),c=world.choose(candidates);openDetail(c.text);};
$('#creation-title').onclick=()=>{openDialog(`<h2>为画卷取个名字</h2><p>你的天地，你来命名。</p><input id="creation-name-input" class="c-search" maxlength="24" aria-label="画卷名称" value="${esc(world.scene.title)}"><div class="c-dialog-actions"><button id="creation-name-save" class="c-primary">题上这个名字</button></div>`);$('#creation-name-save').onclick=()=>{if(world.rename($('#creation-name-input').value)){closeDialog();save();renderWorld();}};};
function openAlbum(){openDialog(`<h2>我的画册</h2><p>新卷从空白开始，当前画会收入画册；认识的字词都能带过去。最多收藏 8 幅旧画。</p><button id="creation-new-scroll" class="c-primary">收好这幅，开启空白新卷 →</button><div class="c-album-grid">${world.album.map((s,i)=>`<div class="c-album-card">${renderPainting(s,{interactive:false,animate:false})}<div><b>${esc(s.title)}</b><button data-open-album="${i}">继续添画 ↗</button><button data-delete-album="${i}" aria-label="删除${esc(s.title)}">×</button></div></div>`).join('')}</div>${!world.album.length?'<p>还没有收起的画卷。先去造一个喜欢的世界吧。</p>':''}`);$('#creation-new-scroll').onclick=()=>{const r=world.newScene();if(!r.ok)return feedback(r.message);pending=null;selected=null;save();renderWorld();closeDialog();feedback('新画卷打开了，旧画已收进画册。想换一种世界试试吗？',true);};$('#creation-dialog-content').onclick=e=>{const b=e.target.closest('[data-open-album],[data-delete-album]');if(!b)return;if(b.dataset.openAlbum!==undefined){world.openAlbum(Number(b.dataset.openAlbum));pending=null;selected=null;save();renderWorld();closeDialog();}else{const i=Number(b.dataset.deleteAlbum),s=world.album[i];openDialog(`<h2>移出画册？</h2><p>「${esc(s.title)}」将从这台设备的画册中删除。想保留它，可以先打开并存为图片。</p><div class="c-dialog-actions"><button id="creation-album-keep" class="c-primary">先留着</button><button id="creation-album-delete" class="c-secondary">删除这幅旧画</button></div>`);$('#creation-album-keep').onclick=openAlbum;$('#creation-album-delete').onclick=()=>{world.deleteAlbum(i);save();openAlbum();};}};}
$('#creation-album').onclick=openAlbum;
$('#creation-export').onclick=()=>{const source=renderPainting(world.scene,{interactive:false,animate:false,labels}),blob=new Blob([source],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=world.scene.title.replace(/[\\/:*?"<>|]/g,'')+'.svg';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);feedback('已导出可独立打开的 SVG 图片，包含这幅画的景物和题名。',true);};
$('#creation-help').onclick=()=>{openDialog(`<h2>你的字，你的世界</h2><p>这里没有关卡顺序，也没有倒计时。你可以从一片空白开始，慢慢造出自己的小天地。</p><div class="c-note">① 挑选部件和摆法，拼出汉字。<br>② 认识过的字可以继续组词，最多四个字。<br>③ 点「造出来」，再点画卷落笔；同一个字词能反复使用。<br>④ 选「挪动」拖动造物；橡皮、撤销可以放心试。</div><p>「木」可以变成「林」「森」，再组成「森林」；「雨＋田」能造出「雷」。有水，才能放鱼和船。雨让植物生长，放晴能遇见彩虹；月亮升起，灯会发亮。</p><p>灵感部件每次会换，但全部部件和配方始终开放。不是所有组合都已收录，暂未收录不代表字词不存在。整字栏保留了部分完整字形，不把所有字都称为独体字。</p><p>画卷只保存在当前浏览器，导出图片可以留念。配音暂时关闭，先一起把世界造得更有趣。</p><div class="c-dialog-actions"><button id="creation-help-start" class="c-primary">开始造物 →</button><a class="c-secondary" href="./glyph-lessons.html">原来的练字小径 ↗</a></div><p><a href="./ARPHICPL.TXT">原描红笔顺资料许可</a></p>`);$('#creation-help-start').onclick=closeDialog;};
function onLeave(){save();}window.addEventListener('pagehide',onLeave);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else syncViewport();});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['+','-','=','0'].includes(e.key))e.preventDefault();if(e.key==='Escape'&&!dialog.open){pending=null;selected=null;renderWorld();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!dialog.open){e.preventDefault();$('#creation-undo').click();}});
renderWorld();renderWorkshop();save();for(const b of document.querySelectorAll('.c-header button,#creation-title,#creation-hand,#creation-eraser,#creation-labels,#creation-export,[data-creation-mode],#creation-bag,#creation-clear,#creation-refresh,#creation-parts-more,#creation-inspire'))b.disabled=false;
if(recovered)feedback('旧画卷数据没有完整读出，先打开了一张新卷。');
